import{_ as e,o as r,c as o,a2 as s}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"運行狀態","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/user-guide/settings/service-status.md","filePath":"zh-HK/user-guide/settings/service-status.md","lastUpdated":1787586465000}'),a={name:"zh-HK/user-guide/settings/service-status.md"};function i(n,t,l,g,d,c){return r(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="運行狀態" tabindex="-1">運行狀態 <a class="header-anchor" href="#運行狀態" aria-label="Permalink to &quot;運行狀態&quot;">​</a></h1><p>運行狀態頁面集中監控 Lertaro 核心後台服務的生命週期健康度，並內建了面向 Service、App 與 Hook 三大核心程序的高效能即時記錄檢視器。頁面路徑為<strong>設定 → 運行狀態</strong>。</p><h2 id="_1-服務狀態與控制" tabindex="-1">1. 服務狀態與控制 <a class="header-anchor" href="#_1-服務狀態與控制" aria-label="Permalink to &quot;1. 服務狀態與控制&quot;">​</a></h2><p>頁面頂部展示後台提權索引服務的運行狀態卡片：</p><ul><li><strong>即時狀態顯示</strong>： <ul><li><strong>就緒（Ready）</strong>：服務運行健康，即時呈現當前已索引的實體檔案與資料夾總項目數。</li><li><strong>索引中（Indexing）</strong>：正在執行初始構建或全量增量更新，顯示動態進度指示器。</li><li><strong>安裝中（Installing）</strong>：正在註冊並部署 Windows 後台服務。</li><li><strong>錯誤（Error）</strong>：服務未運行或遇到異常中斷，顯示醒目的警告標記與錯誤描述。</li></ul></li><li><strong>服務自我修復與安裝按鈕</strong>：當且僅當後台服務尚未安裝或由於系統權限受損進入異常狀態時，頁面會提供<strong>安裝並啟動服務</strong>按鈕；在服務健康運行期間，系統會維持後台持續常駐，避免誤操作導致索引中斷。</li></ul><h2 id="_2-三程序即時記錄檢視器" tabindex="-1">2. 三程序即時記錄檢視器 <a class="header-anchor" href="#_2-三程序即時記錄檢視器" aria-label="Permalink to &quot;2. 三程序即時記錄檢視器&quot;">​</a></h2><p>頁面下方提供了內建記錄終端機，分為三個獨立的標籤頁，分別對應 Lertaro 運行的三大程序：</p><ul><li><strong>App 標籤頁</strong>：記錄前景 WPF 用戶介面、搜尋互動、快捷鍵回應與視窗轉譯相關的操作記錄。</li><li><strong>Hook 標籤頁</strong>：記錄低階全域鍵盤掛鉤獨立程序（<code>Lertaro.Hook.exe</code>）的按鍵擷取與程序隔離狀態。</li><li><strong>Service 標籤頁</strong>：記錄提權 Windows 後台服務（<code>Lertaro.Service.exe</code>）的 USN 記錄檔剖析、磁碟遍歷、記憶體樹構建與 IPC 通訊記錄。</li></ul><h3 id="過濾與記錄清理功能" tabindex="-1">過濾與記錄清理功能 <a class="header-anchor" href="#過濾與記錄清理功能" aria-label="Permalink to &quot;過濾與記錄清理功能&quot;">​</a></h3><ul><li><strong>記錄等級過濾</strong>：下拉方塊支援篩選「全部 / 錯誤 / 警告 / 資訊 / 偵錯」，記錄行按嚴重等級自動呈現不同的顏色標記。</li><li><strong>即時搜尋過濾</strong>：在搜尋框中輸入關鍵字可瞬間對當前記錄內容進行全文過濾，並與等級過濾條件疊加生效。</li><li><strong>安全清空記錄</strong>：按一下<strong>清空記錄</strong>按鈕可清理當前標籤頁的歷史記錄輸出。清理 Service 記錄時會自動透過提權服務代理安全截斷，無需手動提升管理員權限。</li></ul>',10)])])}const _=e(a,[["render",i]]);export{h as __pageData,_ as default};
